pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    address owner;

    function setUp() public {
        c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub()));
        owner = address(this);
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(this));
        vm.prank(owner);
        try c.transferOwnership(newOwner) {
            // successful transfer to a non-zero address is fine in P
        } catch {
            // P reverts only when newOwner == address(0)
        }
        assertTrue(c.owner() != address(0), "owner must never be the zero address");
    }
}
